<?php
declare(strict_types=1);
$sessionPath='/home3/crist668/php_sessions_patrona';
if(!is_dir($sessionPath)||!is_writable($sessionPath)){http_response_code(503);exit('Sesiones no disponibles');}
session_save_path($sessionPath);session_start();
if(empty($_SESSION['patrona_admin_id'])){header('Location: admin.php');exit;}
if(empty($_SESSION['patrona_csrf']))$_SESSION['patrona_csrf']=bin2hex(random_bytes(32));
function te($s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function topbar_url(string $url):bool{return $url===''||$url==='#'||(filter_var($url,FILTER_VALIDATE_URL)&&in_array(strtolower((string)parse_url($url,PHP_URL_SCHEME)),['http','https'],true));}
$error='';$notice=(string)($_SESSION['topbar_notice']??'');unset($_SESSION['topbar_notice']);
$config=[];$items=[];
try{
 $cfg=require __DIR__.'/class/conexion_local.php';
 if(!is_array($cfg)||($cfg['db']??'')!=='crist668_colegio_patrona_laflorida')throw new RuntimeException('Base no autorizada.');
 mysqli_report(MYSQLI_REPORT_ERROR|MYSQLI_REPORT_STRICT);
 $db=new mysqli($cfg['host'],$cfg['user'],$cfg['pass'],$cfg['db']);$db->set_charset('utf8mb4');
 $q=$db->prepare("SELECT * FROM seccion WHERE id_institucion=2 AND nombre_interno='topbar' LIMIT 1");$q->execute();$section=$q->get_result()->fetch_assoc();
 if(!$section)throw new RuntimeException('No existe el contenedor topbar.');
 $sid=(int)$section['id_seccion'];
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!hash_equals((string)$_SESSION['patrona_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Sesión vencida. Recarga la página.');
  if(($section['editable']??'no')!=='si')throw new RuntimeException('Este contenedor no está habilitado para edición.');
  $action=(string)($_POST['accion']??'');$id=max(0,(int)($_POST['id_item']??0));
  if($action==='config'){
   $values=['titulo_bloque'=>trim((string)($_POST['nombre_colegio']??'')),'texto'=>trim((string)($_POST['mensaje']??''))];
   foreach($values as $key=>$value)if(mb_strlen($value)>240)throw new RuntimeException('El texto es demasiado largo.');
   $db->begin_transaction();
   try{foreach($values as $key=>$value){$q=$db->prepare('DELETE FROM seccion_config WHERE id_seccion=? AND clave=?');$q->bind_param('is',$sid,$key);$q->execute();$q=$db->prepare('INSERT INTO seccion_config(id_seccion,clave,valor) VALUES(?,?,?)');$q->bind_param('iss',$sid,$key,$value);$q->execute();}$db->commit();}catch(Throwable $e){$db->rollback();throw $e;}
  }elseif(in_array($action,['save','delete','toggle'],true)){
   if($id){$q=$db->prepare('SELECT * FROM seccion_item WHERE id_item=? AND id_seccion=?');$q->bind_param('ii',$id,$sid);$q->execute();$old=$q->get_result()->fetch_assoc();if(!$old)throw new RuntimeException('Elemento no encontrado.');}
   if($action==='delete'){$q=$db->prepare('DELETE FROM seccion_item WHERE id_item=? AND id_seccion=?');$q->bind_param('ii',$id,$sid);$q->execute();}
   elseif($action==='toggle'){$next=$old['visible']==='si'?'no':'si';$q=$db->prepare('UPDATE seccion_item SET visible=? WHERE id_item=? AND id_seccion=?');$q->bind_param('sii',$next,$id,$sid);$q->execute();}
   else{
    $kind=(string)($_POST['tipo']??'');$valid=['direccion','telefono','correo','enlace','instagram','facebook','youtube','linkedin','x'];
    if(!in_array($kind,$valid,true))throw new RuntimeException('Tipo de elemento no válido.');
    $label=trim((string)($_POST['titulo']??''));$value=trim((string)($_POST['url']??''));
    if($label===''||mb_strlen($label)>120||mb_strlen($value)>500)throw new RuntimeException('Nombre o valor inválido.');
    if($kind==='correo'&&!filter_var($value,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Introduce un correo válido.');
    if($kind==='telefono'&&!preg_match('/^[+0-9 ()-]{6,30}$/',$value))throw new RuntimeException('Introduce un teléfono válido.');
    if(!in_array($kind,['direccion','telefono','correo'],true)&&!topbar_url($value))throw new RuntimeException('Introduce una URL http(s) válida.');
    $visible=($_POST['visible']??'si')==='no'?'no':'si';$orden=max(1,(int)($_POST['orden']??1));
    if($id){$q=$db->prepare('UPDATE seccion_item SET etiqueta=?,titulo=?,url=?,visible=?,orden=? WHERE id_item=? AND id_seccion=?');$q->bind_param('ssssiii',$kind,$label,$value,$visible,$orden,$id,$sid);}
    else{$q=$db->prepare('INSERT INTO seccion_item(id_seccion,etiqueta,titulo,url,visible,orden) VALUES(?,?,?,?,?,?)');$q->bind_param('issssi',$sid,$kind,$label,$value,$visible,$orden);}
    $q->execute();
   }
  }else throw new RuntimeException('Acción no permitida.');
  $_SESSION['topbar_notice']='Cambios guardados correctamente.';header('Location: editar_topbar.php');exit;
 }
 $q=$db->prepare('SELECT clave,valor FROM seccion_config WHERE id_seccion=?');$q->bind_param('i',$sid);$q->execute();foreach($q->get_result()->fetch_all(MYSQLI_ASSOC) as $row)$config[$row['clave']]=$row['valor'];
 $q=$db->prepare('SELECT * FROM seccion_item WHERE id_seccion=? ORDER BY orden,id_item');$q->bind_param('i',$sid);$q->execute();$items=$q->get_result()->fetch_all(MYSQLI_ASSOC);
}catch(Throwable $e){error_log('Editor topbar Patrona: '.$e->getMessage());$error=$e->getMessage();}
$edit=null;foreach($items as $item)if((int)$item['id_item']===(int)($_GET['item']??0))$edit=$item;
$types=['direccion'=>'Dirección','telefono'=>'Teléfono','correo'=>'Correo electrónico','enlace'=>'Enlace destacado','instagram'=>'Instagram','facebook'=>'Facebook','youtube'=>'YouTube','linkedin'=>'LinkedIn','x'=>'X (Twitter)'];
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Barra superior | Patrona CMS</title><link rel="stylesheet" href="assets/admin/css/patrona-panel.css?v=4"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><style>
*{box-sizing:border-box}body{margin:0;background:#f2f5fa;color:#162b48;font:15px/1.5 system-ui,sans-serif}.shell{max-width:1180px;margin:auto;padding:28px 22px}.heading{display:flex;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap}.heading a,.link{color:#175da5;text-decoration:none}.card{background:white;border:1px solid #dce4ef;border-radius:14px;margin-top:20px;padding:24px;box-shadow:0 5px 16px #102b5010}.card h2{font-size:19px;margin:0 0 7px}.muted{color:#64748b;font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.field{display:flex;flex-direction:column;gap:6px;font-weight:650;font-size:13px}.field input,.field select{width:100%;padding:11px 12px;border:1px solid #cad6e5;border-radius:8px;font:inherit;font-weight:400;background:white}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;background:#183e6b;color:white;border:0;border-radius:8px;padding:11px 16px;min-height:42px;font:600 13px system-ui;cursor:pointer;text-decoration:none}.btn.secondary{background:#fff;color:#183e6b;border:1px solid #cbd5e1}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #e8edf5;padding:13px 10px}th{font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:#66758a}td{font-size:14px}.actions{display:flex;gap:7px}.actions form{display:inline}.actions button,.actions a{display:inline-flex;align-items:center;justify-content:center;min-width:35px;min-height:35px;border:1px solid #d6e1ed;border-radius:7px;background:white;color:#21476d;cursor:pointer;text-decoration:none}.pill{border-radius:20px;padding:4px 9px;background:#e3f5ed;color:#157347;font-size:12px}.pill.off{background:#f2f4f8;color:#64748b}.preview{background:#174675;color:#fff;border-radius:9px;padding:12px 16px;display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap}.preview-list{display:flex;flex-wrap:wrap;gap:14px}.preview-list span{display:inline-flex;gap:6px;align-items:center}.notice{padding:12px 15px;border-radius:8px;background:#e8f7ee;color:#176a3b}.error{background:#ffebeb;color:#9c2222}.type-icons{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.type-icons button{background:#f5f8fc;border:1px solid #dbe4f0;border-radius:8px;padding:9px 13px;cursor:pointer}.type-icons button.selected{background:#e8f2ff;border-color:#1765b8;color:#0e4b87}@media(max-width:680px){.grid{grid-template-columns:1fr}.shell{padding:14px}.card{padding:17px}.preview{flex-direction:column}}
</style></head><body><main class="shell"><div class="heading"><div><small class="muted">CMS / CONTENEDORES</small><h1>Barra superior</h1><p class="muted">Administra los datos y redes sociales que aparecen sobre el menú principal.</p></div><div><a class="btn secondary" href="admin.php?panel=contenedores"><i class="bi bi-arrow-left"></i> Volver</a> <a class="btn" href="index.php" target="_blank" rel="noopener"><i class="bi bi-eye"></i> Visualizar</a></div></div>
<?php if($error):?><p class="notice error"><?=te($error)?></p><?php endif;?><?php if($notice):?><p class="notice"><?=te($notice)?></p><?php endif;?>
<?php if(isset($sid)):?>
<section class="card"><h2>Vista previa de la barra superior</h2><p class="muted">Así se organizarán los elementos visibles; la apariencia definitiva utiliza los estilos del sitio.</p><div class="preview"><strong><?=te(($config['titulo_bloque']??'')?:'COLEGIO PATRONA DE LOURDES · LA FLORIDA')?></strong><div class="preview-list"><?php foreach($items as $i):if(($i['visible']??'si')!=='si')continue;?><span><i class="bi bi-<?=te(['direccion'=>'geo-alt','telefono'=>'telephone','correo'=>'envelope','enlace'=>'box-arrow-up-right','instagram'=>'instagram','facebook'=>'facebook','youtube'=>'youtube','linkedin'=>'linkedin','x'=>'twitter-x'][$i['etiqueta']??'']??'link-45deg')?>"></i><?=te($i['titulo'])?></span><?php endforeach;?></div></div></section>
<section class="card"><h2>General</h2><p class="muted">Identidad institucional y mensaje opcional. El mensaje solo aparece si no has agregado elementos visibles.</p><form method="post"><input type="hidden" name="csrf" value="<?=te($_SESSION['patrona_csrf'])?>"><input type="hidden" name="accion" value="config"><div class="grid"><label class="field">Nombre institucional<input name="nombre_colegio" maxlength="240" value="<?=te($config['titulo_bloque']??'COLEGIO PATRONA DE LOURDES · LA FLORIDA')?>"></label><label class="field">Mensaje alternativo<input name="mensaje" maxlength="240" value="<?=te($config['texto']??'')?>"></label></div><p><button class="btn"><i class="bi bi-check2"></i> Guardar general</button></p></form></section>
<section class="card"><div class="toolbar"><div><h2>Datos de contacto y redes sociales</h2><p class="muted">Puedes agregar, editar, ocultar, ordenar o eliminar cada elemento.</p></div><a class="btn" href="#form-elemento"><i class="bi bi-plus-circle"></i> Agregar elemento</a></div><div class="table-wrap"><table><thead><tr><th>Orden</th><th>Tipo</th><th>Nombre</th><th>Valor / enlace</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=(int)$i['orden']?></td><td><?=te($types[$i['etiqueta']??'']??'Otro')?></td><td><strong><?=te($i['titulo'])?></strong></td><td><?=te(mb_strimwidth((string)$i['url'],0,48,'…'))?></td><td><span class="pill <?=($i['visible']??'si')==='si'?'':'off'?>"><?=($i['visible']??'si')==='si'?'Visible':'Oculto'?></span></td><td><div class="actions"><a href="?item=<?=(int)$i['id_item']?>#form-elemento" title="Editar" aria-label="Editar <?=te($i['titulo'])?>"><i class="bi bi-pencil-square"></i></a><form method="post"><input type="hidden" name="csrf" value="<?=te($_SESSION['patrona_csrf'])?>"><input type="hidden" name="accion" value="toggle"><input type="hidden" name="id_item" value="<?=(int)$i['id_item']?>"><button title="Cambiar visibilidad" aria-label="Cambiar visibilidad"><i class="bi bi-eye<?=($i['visible']??'si')==='si'?'':'-slash'?>"></i></button></form><form method="post" onsubmit="return confirm('¿Eliminar este elemento de la barra superior?')"><input type="hidden" name="csrf" value="<?=te($_SESSION['patrona_csrf'])?>"><input type="hidden" name="accion" value="delete"><input type="hidden" name="id_item" value="<?=(int)$i['id_item']?>"><button title="Eliminar" aria-label="Eliminar"><i class="bi bi-trash"></i></button></form></div></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="6" class="muted">Todavía no hay elementos. Agrega una dirección, teléfono, correo o red social.</td></tr><?php endif;?></tbody></table></div></section>
<section class="card" id="form-elemento"><h2><?=$edit?'Editar elemento':'Agregar elemento'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=te($_SESSION['patrona_csrf'])?>"><input type="hidden" name="accion" value="save"><input type="hidden" name="id_item" value="<?=(int)($edit['id_item']??0)?>"><div class="grid"><label class="field">Tipo de elemento<select name="tipo" id="tipo" required><?php foreach($types as $key=>$label):?><option value="<?=te($key)?>" <?=($edit['etiqueta']??'')===$key?'selected':''?>><?=te($label)?></option><?php endforeach;?></select></label><label class="field">Nombre visible<input name="titulo" maxlength="120" required placeholder="Ej.: Instagram, Secretaría, Dirección" value="<?=te($edit['titulo']??'')?>"></label><label class="field">Dirección, teléfono, correo o URL<input name="url" maxlength="500" id="valor" placeholder="https://... o contacto@colegio.cl" value="<?=te($edit['url']??'')?>"></label><label class="field">Orden<input type="number" name="orden" min="1" value="<?=(int)($edit['orden']??count($items)+1)?>"></label><label class="field">Visibilidad<select name="visible"><option value="si" <?=($edit['visible']??'si')==='si'?'selected':''?>>Visible</option><option value="no" <?=($edit['visible']??'si')==='no'?'selected':''?>>Oculto</option></select></label></div><p class="muted">Para redes sociales y enlaces, utiliza una URL completa con https://. Para dirección, escribe la ubicación; para teléfono, el número; para correo, la dirección electrónica.</p><button class="btn"><i class="bi bi-check2-circle"></i> Guardar elemento</button> <?php if($edit):?><a class="btn secondary" href="editar_topbar.php">Cancelar edición</a><?php endif;?></form></section>
<?php endif;?></main></body></html>
